import{_ as a,o as e,c as l,ag as n}from"./chunks/framework.C9sp7nFj.js";const h=JSON.parse('{"title":"SetSyncSignal 发送同步信号","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/21. 主从运动指令/SetSyncSignal.md","filePath":"3. 指令/21. 主从运动指令/SetSyncSignal.md","lastUpdated":1778862643000}'),r={name:"3. 指令/21. 主从运动指令/SetSyncSignal.md"};function d(i,t,o,S,c,s){return e(),l("div",null,[...t[0]||(t[0]=[n('<h1 id="setsyncsignal-发送同步信号" tabindex="-1">SetSyncSignal 发送同步信号 <a class="header-anchor" href="#setsyncsignal-发送同步信号" aria-label="Permalink to &quot;SetSyncSignal 发送同步信号&quot;">​</a></h1><p>该指令用于使主机器人将信息索引值发送给对应的从机器人。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetSyncSignal([MSGroup], SyncId, SignalId) SetSyncSignal([主从组], 协同标识, 信号索引)</p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>[MSGroup]</td><td>enum</td><td>机器人协同运动时的主从组参数，用于在多机协同过程中区分所启用的机器人协同方式。详见下方 MSGroup 取值说明。</td><td>DEFAULT（仅限从机器人选择）</td></tr><tr><td>SyncId</td><td>SYNCID 变量</td><td>机器人协同标识 ID 号，用于本机与协同机器人之间进行协同校验，主从机器人 ID 一致时才为有效协同。</td><td></td></tr><tr><td>SignalId</td><td>int 或 INT 变量</td><td>机器人信号索引值，当主机器人执行到该指令时，根据协同标识告知与之协同运动的从机器人，本机器人已运行到指定行。</td><td></td></tr></tbody></table><blockquote><p><strong>MSGroup 取值说明</strong>：</p><ul><li>MSGroup1：第一组主从组参数，仅限主机器人选择</li><li>MSGroup2：第二组主从组参数，仅限主机器人选择</li><li>MSGroup3：第三组主从组参数，仅限主机器人选择</li><li>MSGroup4：第四组主从组参数，仅限主机器人选择</li><li>MSGroup5：第五组主从组参数，仅限主机器人选择</li><li>MSGroup6：第六组主从组参数，仅限主机器人选择</li><li>MSGroup7：第七组主从组参数，仅限主机器人选择</li><li>DEFAULT：缺省类型，仅限从机器人选择</li></ul></blockquote>',9)])])}const u=a(r,[["render",d]]);export{h as __pageData,u as default};
